  /**
   * @method
   * @name digifinex#fetchCurrencies
   * @description fetches all available currencies on an exchange
   * @see
   * https://docs.digifinex.com/en-ww/spot/v3/rest.html#get-currency-deposit-and-withdrawal-information
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an associative dictionary of currencies
   */
  std::shared_future<std::any>
  fetchCurrencies(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any response =
                            awaitValue(this->publicSpotGetCurrencies(params));
                        //
                        //     {
                        //         "data":[
                        //             {
                        //                 "deposit_status":1,
                        //                 "min_deposit_amount":10,
                        //                 "withdraw_fee_rate":0,
                        //                 "min_withdraw_amount":10,
                        //                 "min_withdraw_fee":5,
                        //                 "currency":"USDT",
                        //                 "withdraw_fee_currency":"USDT",
                        //                 "withdraw_status":0,
                        //                 "chain":"OMNI"
                        //             },
                        //             {
                        //                 "deposit_status":1,
                        //                 "min_deposit_amount":10,
                        //                 "withdraw_fee_rate":0,
                        //                 "min_withdraw_amount":10,
                        //                 "min_withdraw_fee":3,
                        //                 "currency":"USDT",
                        //                 "withdraw_fee_currency":"USDT",
                        //                 "withdraw_status":1,
                        //                 "chain":"ERC20"
                        //             },
                        //             {
                        //                 "deposit_status":0,
                        //                 "min_deposit_amount":0,
                        //                 "withdraw_fee_rate":0,
                        //                 "min_withdraw_amount":0,
                        //                 "min_withdraw_fee":0,
                        //                 "currency":"DGF13",
                        //                 "withdraw_fee_currency":"DGF13",
                        //                 "withdraw_status":0,
                        //                 "chain":""
                        //             },
                        //         ],
                        //         "code":200
                        //     }
                        //
                        std::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        std::any groupedById =
                            this->groupBy(data, std::string("currency"));
                        std::any values = getObjectValues(groupedById);
                        return this->parseCurrencies(values);
                      })
        .share();
  }

  std::any parseCurrency(std::any rawCurrency) override {
    std::any networkEntries = rawCurrency;
    std::any firstEntry = this->safeDict(
        networkEntries, 0, ccxt::dict{}); // it must have at least one entry
    std::any id = this->safeString(firstEntry, std::string("currency"));
    std::any code = this->safeCurrencyCode(id);
    std::any networks = ccxt::dict{};
    for (std::any j = 0; isLessThan(j, getArrayLength(networkEntries));
         postFixIncrement(j)) {
      std::any networkEntry = ::getValue(networkEntries, j);
      std::any networkId = this->safeString2(networkEntry, std::string("chain"),
                                             std::string("currency"));
      std::any networkCode = this->networkIdToCode(networkId, code);
      if (isTrue(!isEqual(networkCode, std::any{}))) {
        ::setValue(
            networks, networkCode,
            ccxt::dict{
                {std::string("id"), networkId},
                {std::string("network"), networkCode},
                {std::string("active"), std::any{}},
                {std::string("deposit"),
                 isEqual(this->safeInteger(networkEntry,
                                           std::string("deposit_status")),
                         1)},
                {std::string("withdraw"),
                 isEqual(this->safeInteger(networkEntry,
                                           std::string("withdraw_status")),
                         1)},
                {std::string("fee"),
                 this->safeNumber(networkEntry,
                                  std::string("min_withdraw_fee"))},
                {std::string("precision"), std::any{}},
                {std::string("limits"),
                 ccxt::dict{
                     {std::string("withdraw"),
                      ccxt::dict{
                          {std::string("min"),
                           this->safeNumber(
                               networkEntry,
                               std::string("min_withdraw_amount"))},
                          {std::string("max"), std::any{}},
                      }},
                     {std::string("deposit"),
                      ccxt::dict{
                          {std::string("min"),
                           this->safeNumber(networkEntry,
                                            std::string("min_deposit_amount"))},
                          {std::string("max"), std::any{}},
                      }},
                 }},
                {std::string("info"), networkEntry},
            });
      }
    }
    return this->safeCurrencyStructure(ccxt::dict{
        {std::string("id"), id},
        {std::string("code"), code},
        {std::string("info"), networkEntries},
        {std::string("networks"), networks},
    });
  }

  /**
   * @method
   * @name digifinex#fetchMarkets
   * @description retrieves data on all markets for digifinex
   * @see
   * https://docs.digifinex.com/en-ww/spot/v3/rest.html#all-the-market-description
   * @see
   * https://docs.digifinex.com/en-ww/spot/v3/rest.html#spot-trading-pair-symbol
   * @see
   * https://docs.digifinex.com/en-ww/spot/v3/rest.html#margin-trading-pair-symbol
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#instruments
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<std::any>
  fetchMarkets(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any options = this->safeValue(
                     this->options, std::string("fetchMarkets"), ccxt::dict{});
                 std::any method =
                     this->safeString(options, std::string("method"),
                                      std::string("fetch_markets_v2"));
                 if (isTrue(isEqual(method, std::string("fetch_markets_v2")))) {
                   return awaitValue(this->fetchMarketsV2(params));
                 }
                 return awaitValue(this->fetchMarketsV1(params));
               })
        .share();
  }

  virtual std::shared_future<std::any>
  fetchMarketsV2(std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any defaultType = this->safeString(
                     this->options, std::string("defaultType"));
                 std::any marginModequeryVariable =
                     this->handleMarginModeAndParams(
                         std::string("fetchMarketsV2"), params);
                 std::any marginMode = ::getValue(marginModequeryVariable, 0);
                 std::any query = ::getValue(marginModequeryVariable, 1);
                 std::any promisesRaw = ccxt::list{};
                 if (isTrue(!isEqual(marginMode, std::any{}))) {
                   arrayPush(promisesRaw,
                             this->publicSpotGetMarginSymbols(query));
                 } else {
                   arrayPush(promisesRaw,
                             this->publicSpotGetTradesSymbols(query));
                 }
                 arrayPush(promisesRaw,
                           this->publicSwapGetPublicInstruments(params));
                 std::any promises = awaitValue(promiseAll(promisesRaw));
                 std::any spotMarkets = ::getValue(promises, 0);
                 std::any swapMarkets = ::getValue(promises, 1);
                 //
                 // spot and margin
                 //
                 //     {
                 //         "symbol_list":[
                 //             {
                 //                 "order_types":["LIMIT","MARKET"],
                 //                 "quote_asset":"USDT",
                 //                 "minimum_value":2,
                 //                 "amount_precision":4,
                 //                 "status":"TRADING",
                 //                 "minimum_amount":0.0001,
                 //                 "symbol":"BTC_USDT",
                 //                 "is_allow":1,
                 //                 "zone":"MAIN",
                 //                 "base_asset":"BTC",
                 //                 "price_precision":2
                 //             }
                 //         ],
                 //         "code":0
                 //     }
                 //
                 // swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": [
                 //             {
                 //                 "instrument_id": "BTCUSDTPERP",
                 //                 "type": "REAL",
                 //                 "contract_type": "PERPETUAL",
                 //                 "base_currency": "BTC",
                 //                 "quote_currency": "USDT",
                 //                 "clear_currency": "USDT",
                 //                 "contract_value": "0.001",
                 //                 "contract_value_currency": "BTC",
                 //                 "is_inverse": false,
                 //                 "is_trading": true,
                 //                 "status": "ONLINE",
                 //                 "price_precision": 4,
                 //                 "tick_size": "0.0001",
                 //                 "min_order_amount": 1,
                 //                 "open_max_limits": [
                 //                     {
                 //                         "leverage": "50",
                 //                         "max_limit": "1000000"
                 //                     }
                 //                 ]
                 //             },
                 //         ]
                 //     }
                 //
                 std::any spotData = this->safeValue(
                     spotMarkets, std::string("symbol_list"), ccxt::list{});
                 std::any swapData = this->safeValue(
                     swapMarkets, std::string("data"), ccxt::list{});
                 std::any response = this->arrayConcat(spotData, swapData);
                 std::any result = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(response));
                      postFixIncrement(i)) {
                   std::any market = ::getValue(response, i);
                   std::any id =
                       this->safeString2(market, std::string("symbol"),
                                         std::string("instrument_id"));
                   std::any baseId =
                       this->safeString2(market, std::string("base_asset"),
                                         std::string("base_currency"));
                   std::any quoteId =
                       this->safeString2(market, std::string("quote_asset"),
                                         std::string("quote_currency"));
                   std::any settleId =
                       this->safeString(market, std::string("clear_currency"));
                   std::any base = this->safeCurrencyCode(baseId);
                   std::any quote = this->safeCurrencyCode(quoteId);
                   std::any settle = this->safeCurrencyCode(settleId);
                   //
                   // The status is documented in the exchange API docs as
                   // follows: TRADING, HALT (delisted), BREAK (trading paused)
                   // https://docs.digifinex.vip/en-ww/v3/#/public/spot/symbols
                   // However, all spot markets actually have status === 'HALT'
                   // despite that they appear to be active on the exchange
                   // website. Apparently, we can't trust this status. const
                   // status = this.safeString (market, 'status'); const active
                   // = (status === 'TRADING');
                   //
                   std::any isAllowed =
                       this->safeInteger(market, std::string("is_allow"), 1);
                   std::any type =
                       (isTrue((isEqual(defaultType, std::string("margin"))))
                            ? std::any(std::string("margin"))
                            : std::any(std::string("spot")));
                   std::any spot = isEqual(settle, std::any{});
                   std::any swap = !isTrue(spot);
                   std::any margin = (isTrue((!isEqual(marginMode, std::any{})))
                                          ? std::any(true)
                                          : std::any(std::any{}));
                   std::any symbol = add(add(base, std::string("/")), quote);
                   std::any isInverse = std::any{};
                   std::any isLinear = std::any{};
                   if (isTrue(swap)) {
                     type = std::string("swap");
                     symbol = add(add(add(add(base, std::string("/")), quote),
                                      std::string(":")),
                                  settle);
                     isInverse =
                         this->safeValue(market, std::string("is_inverse"));
                     isLinear = (isTrue((!isEqual(isInverse, true)))
                                     ? std::any(true)
                                     : std::any(false));
                     std::any isTrading =
                         this->safeValue(market, std::string("isTrading"));
                     if (isTrue(isEqual(isTrading, true))) {
                       isAllowed = 1;
                     }
                   }
                   std::any isActive = (!isEqual(isAllowed, 0));
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("id"), id},
                           {std::string("symbol"), symbol},
                           {std::string("base"), base},
                           {std::string("quote"), quote},
                           {std::string("settle"), settle},
                           {std::string("baseId"), baseId},
                           {std::string("quoteId"), quoteId},
                           {std::string("settleId"), settleId},
                           {std::string("type"), type},
                           {std::string("spot"), spot},
                           {std::string("margin"), margin},
                           {std::string("swap"), swap},
                           {std::string("future"), false},
                           {std::string("option"), false},
                           {std::string("active"), isActive},
                           {std::string("contract"), swap},
                           {std::string("linear"), isLinear},
                           {std::string("inverse"), isInverse},
                           {std::string("contractSize"),
                            this->safeNumber(market,
                                             std::string("contract_value"))},
                           {std::string("expiry"), std::any{}},
                           {std::string("expiryDatetime"), std::any{}},
                           {std::string("strike"), std::any{}},
                           {std::string("optionType"), std::any{}},
                           {std::string("precision"),
                            ccxt::dict{
                                {std::string("amount"),
                                 this->parseNumber(
                                     this->parsePrecision(this->safeString(
                                         market,
                                         std::string("amount_precision"))))},
                                {std::string("price"),
                                 this->parseNumber(
                                     this->parsePrecision(this->safeString(
                                         market,
                                         std::string("price_precision"))))},
                            }},
                           {std::string("limits"),
                            ccxt::dict{
                                {std::string("leverage"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("amount"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber2(
                                          market, std::string("minimum_amount"),
                                          std::string("min_order_amount"))},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("price"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market, std::string("tick_size"))},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("cost"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market,
                                          std::string("minimum_value"))},
                                     {std::string("max"), std::any{}},
                                 }},
                            }},
                           {std::string("created"), std::any{}},
                           {std::string("info"), market},
                       });
                 }
                 return result;
               })
        .share();
  }

  virtual std::shared_future<std::any>
  fetchMarketsV1(std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any response =
                     awaitValue(this->publicSpotGetMarkets(params));
                 //
                 //     {
                 //         "data": [
                 //             {
                 //                 "volume_precision":4,
                 //                 "price_precision":2,
                 //                 "market":"btc_usdt",
                 //                 "min_amount":2,
                 //                 "min_volume":0.0001
                 //             },
                 //         ],
                 //         "date":1564507456,
                 //         "code":0
                 //     }
                 //
                 std::any markets = this->safeValue(
                     response, std::string("data"), ccxt::list{});
                 std::any result = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(markets));
                      postFixIncrement(i)) {
                   std::any market = ::getValue(markets, i);
                   std::any id =
                       this->safeString(market, std::string("market"));
                   if (isTrue(isEqual(id, std::any{}))) {
                     throw ExchangeError(toString(
                         add(this->id,
                             std::string(" fetchMarketsV1() missing id"))));
                   }
                   std::any baseIdquoteIdVariable = split(id, std::string("_"));
                   std::any baseId = ::getValue(baseIdquoteIdVariable, 0);
                   std::any quoteId = ::getValue(baseIdquoteIdVariable, 1);
                   std::any base = this->safeCurrencyCode(baseId);
                   std::any quote = this->safeCurrencyCode(quoteId);
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("id"), id},
                           {std::string("symbol"),
                            add(add(base, std::string("/")), quote)},
                           {std::string("base"), base},
                           {std::string("quote"), quote},
                           {std::string("settle"), std::any{}},
                           {std::string("baseId"), baseId},
                           {std::string("quoteId"), quoteId},
                           {std::string("settleId"), std::any{}},
                           {std::string("type"), std::string("spot")},
                           {std::string("spot"), true},
                           {std::string("margin"), std::any{}},
                           {std::string("swap"), false},
                           {std::string("future"), false},
                           {std::string("option"), false},
                           {std::string("active"), std::any{}},
                           {std::string("contract"), false},
                           {std::string("linear"), std::any{}},
                           {std::string("inverse"), std::any{}},
                           {std::string("contractSize"), std::any{}},
                           {std::string("expiry"), std::any{}},
                           {std::string("expiryDatetime"), std::any{}},
                           {std::string("strike"), std::any{}},
                           {std::string("optionType"), std::any{}},
                           {std::string("precision"),
                            ccxt::dict{
                                {std::string("price"),
                                 this->parseNumber(
                                     this->parsePrecision(this->safeString(
                                         market,
                                         std::string("price_precision"))))},
                                {std::string("amount"),
                                 this->parseNumber(
                                     this->parsePrecision(this->safeString(
                                         market,
                                         std::string("volume_precision"))))},
                            }},
                           {std::string("limits"),
                            ccxt::dict{
                                {std::string("leverage"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("amount"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market, std::string("min_volume"))},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("price"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("cost"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market, std::string("min_amount"))},
                                     {std::string("max"), std::any{}},
                                 }},
                            }},
                           {std::string("info"), market},
                       });
                 }
                 return result;
               })
        .share();
  }

  std::any parseBalance(std::any response) override {
    //
    // spot and margin
    //
    //     {
    //         "currency": "BTC",
    //         "free": 4723846.89208129,
    //         "total": 0
    //     }
    //
    // swap
    //
    //     {
    //         "equity": "0",
    //         "currency": "BTC",
    //         "margin": "0",
    //         "frozen_margin": "0",
    //         "frozen_money": "0",
    //         "margin_ratio": "0",
    //         "realized_pnl": "0",
    //         "avail_balance": "0",
    //         "unrealized_pnl": "0",
    //         "time_stamp": 1661487402396
    //     }
    //
    std::any result = ccxt::dict{
        {std::string("info"), response},
    };
    for (std::any i = 0; isLessThan(i, getArrayLength(response));
         postFixIncrement(i)) {
      std::any balance = ::getValue(response, i);
      std::any currencyId = this->safeString(balance, std::string("currency"));
      std::any code = this->safeCurrencyCode(currencyId);
      std::any account = this->account();
      std::any free = this->safeString2(balance, std::string("free"),
                                        std::string("avail_balance"));
      std::any total = this->safeString2(balance, std::string("total"),
                                         std::string("equity"));
      ::setValue(account, std::string("free"), free);
      ::setValue(account, std::string("used"),
                 ccxt::Precise::stringSub(total, free));
      ::setValue(account, std::string("total"), total);
      if (isTrue(!isEqual(code, std::any{}))) {
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name digifinex#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#spot-account-assets
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#margin-assets
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#accountbalance
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<std::any>
  fetchBalance(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any marketType = std::any{};
                 std::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchBalance"), std::any{}, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 std::any marginModequeryVariable =
                     this->handleMarginModeAndParams(
                         std::string("fetchBalance"), params);
                 std::any marginMode = ::getValue(marginModequeryVariable, 0);
                 std::any query = ::getValue(marginModequeryVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(
                         isTrue(!isEqual(marginMode, std::any{})) ||
                         isTrue(isEqual(marketType, std::string("margin"))))) {
                   marketType = std::string("margin");
                   response =
                       awaitValue(this->privateSpotGetMarginAssets(query));
                 } else if (isTrue(isEqual(marketType, std::string("spot")))) {
                   response = awaitValue(this->privateSpotGetSpotAssets(query));
                 } else if (isTrue(isEqual(marketType, std::string("swap")))) {
                   response =
                       awaitValue(this->privateSwapGetAccountBalance(query));
                 } else {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(
                           " fetchBalance() not support this market type"))));
                 }
                 //
                 // spot and margin
                 //
                 //     {
                 //         "code": 0,
                 //         "list": [
                 //             {
                 //                 "currency": "BTC",
                 //                 "free": 4723846.89208129,
                 //                 "total": 0
                 //             },
                 //             ...
                 //         ]
                 //     }
                 //
                 // swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": [
                 //             {
                 //                 "equity": "0",
                 //                 "currency": "BTC",
                 //                 "margin": "0",
                 //                 "frozen_margin": "0",
                 //                 "frozen_money": "0",
                 //                 "margin_ratio": "0",
                 //                 "realized_pnl": "0",
                 //                 "avail_balance": "0",
                 //                 "unrealized_pnl": "0",
                 //                 "time_stamp": 1661487402396
                 //             },
                 //             ...
                 //         ]
                 //     }
                 //
                 std::any balanceRequest =
                     (isTrue((isEqual(marketType, std::string("swap"))))
                          ? std::any(std::string("data"))
                          : std::any(std::string("list")));
                 std::any balances =
                     this->safeValue(response, balanceRequest, ccxt::list{});
                 return this->parseBalance(balances);
               })
        .share();
  }

  /**
   * @method
   * @name digifinex#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#get-orderbook
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#orderbook
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<std::any>
  fetchOrderBook(std::any symbol, std::any limit = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any marketTypequeryVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchOrderBook"), market, params);
                 std::any marketType = ::getValue(marketTypequeryVariable, 0);
                 std::any query = ::getValue(marketTypequeryVariable, 1);
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(marketType, std::string("swap")))) {
                   ::setValue(request, std::string("instrument_id"),
                              ::getValue(market, std::string("id")));
                   response = awaitValue(this->publicSwapGetPublicDepth(
                       this->extend(request, query)));
                 } else {
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   response = awaitValue(this->publicSpotGetOrderBook(
                       this->extend(request, query)));
                 }
                 //
                 // spot
                 //
                 //     {
                 //         "bids": [
                 //             [9605.77,0.0016],
                 //             [9605.46,0.0003],
                 //             [9602.04,0.0127],
                 //         ],
                 //         "asks": [
                 //             [9627.22,0.025803],
                 //             [9627.12,0.168543],
                 //             [9626.52,0.0011529],
                 //         ],
                 //         "date":1564509499,
                 //         "code":0
                 //     }
                 //
                 // swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": {
                 //             "instrument_id": "BTCUSDTPERP",
                 //             "timestamp": 1667975290425,
                 //             "asks": [
                 //                 ["18384.7",3492],
                 //                 ["18402.7",5000],
                 //                 ["18406.7",5000],
                 //             ],
                 //             "bids": [
                 //                 ["18366.2",4395],
                 //                 ["18364.3",3070],
                 //                 ["18359.4",5000],
                 //             ]
                 //         }
                 //     }
                 //
                 std::any timestamp = std::any{};
                 std::any orderBook = std::any{};
                 if (isTrue(isEqual(marketType, std::string("swap")))) {
                   orderBook = this->safeValue(response, std::string("data"),
                                               ccxt::dict{});
                   timestamp =
                       this->safeInteger(orderBook, std::string("timestamp"));
                 } else {
                   orderBook = response;
                   timestamp =
                       this->safeTimestamp(response, std::string("date"));
                 }
                 return this->parseOrderBook(
                     orderBook, ::getValue(market, std::string("symbol")),
                     timestamp);
               })
        .share();
  }

  /**
   * @method
   * @name digifinex#fetchTickers
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#ticker-price
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#tickers
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTickers(std::any symbols = std::any{},
               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols);
                 std::any first = this->safeString(symbols, 0);
                 std::any market = std::any{};
                 if (isTrue(!isEqual(first, std::any{}))) {
                   market = this->market(first);
                 }
                 std::any type = std::any{};
                 std::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchTickers"), market, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 std::any request = ccxt::dict{};
                 std::any response = std::any{};
                 if (isTrue(isEqual(type, std::string("swap")))) {
                   response = awaitValue(this->publicSwapGetPublicTickers(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->publicSpotGetTicker(
                       this->extend(request, params)));
                 }
                 //
                 // spot
                 //
                 //    {
                 //        "ticker": [{
                 //            "vol": 40717.4461,
                 //            "change": -1.91,
                 //            "base_vol": 392447999.65374,
                 //            "sell": 9592.23,
                 //            "last": 9592.22,
                 //            "symbol": "btc_usdt",
                 //            "low": 9476.24,
                 //            "buy": 9592.03,
                 //            "high": 9793.87
                 //        }],
                 //        "date": 1589874294,
                 //        "code": 0
                 //    }
                 //
                 // swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": [
                 //             {
                 //                 "instrument_id": "SUSHIUSDTPERP",
                 //                 "index_price": "1.1297",
                 //                 "mark_price": "1.1289",
                 //                 "max_buy_price": "1.1856",
                 //                 "min_sell_price": "1.0726",
                 //                 "best_bid": "1.1278",
                 //                 "best_bid_size": "500",
                 //                 "best_ask": "1.1302",
                 //                 "best_ask_size": "471",
                 //                 "high_24h": "1.2064",
                 //                 "open_24h": "1.1938",
                 //                 "low_24h": "1.1239",
                 //                 "last": "1.1302",
                 //                 "last_qty": "29",
                 //                 "volume_24h": "4946163",
                 //                 "price_change_percent":
                 //                 "-0.053275255486681085", "open_interest":
                 //                 "-", "timestamp": 1663222782100
                 //             },
                 //             ...
                 //         ]
                 //     }
                 //
                 std::any result = ccxt::dict{};
                 std::any tickers =
                     this->safeValue2(response, std::string("ticker"),
                                      std::string("data"), ccxt::list{});
                 std::any date =
                     this->safeInteger(response, std::string("date"));
                 for (std::any i = 0; isLessThan(i, getArrayLength(tickers));
                      postFixIncrement(i)) {
                   std::any rawTicker = this->extend(
                       ccxt::dict{
                           {std::string("date"), date},
                       },
                       ::getValue(tickers, i));
                   std::any ticker = this->parseTicker(rawTicker);
                   std::any symbol = ::getValue(ticker, std::string("symbol"));
                   if (isTrue(!isEqual(symbol, std::any{}))) {
                     ::setValue(result, symbol, ticker);
                   }
                 }
                 return this->filterByArrayTickers(
                     result, std::string("symbol"), symbols);
               })
        .share();
  }

  /**
   * @method
   * @name digifinex#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#ticker-price
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#ticker
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTicker(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{};
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   ::setValue(request, std::string("instrument_id"),
                              ::getValue(market, std::string("id")));
                   response = awaitValue(this->publicSwapGetPublicTicker(
                       this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   response = awaitValue(this->publicSpotGetTicker(
                       this->extend(request, params)));
                 }
                 //
                 // spot
                 //
                 //    {
                 //        "ticker": [{
                 //            "vol": 40717.4461,
                 //            "change": -1.91,
                 //            "base_vol": 392447999.65374,
                 //            "sell": 9592.23,
                 //            "last": 9592.22,
                 //            "symbol": "btc_usdt",
                 //            "low": 9476.24,
                 //            "buy": 9592.03,
                 //            "high": 9793.87
                 //        }],
                 //        "date": 1589874294,
                 //        "code": 0
                 //    }
                 //
                 // swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": {
                 //             "instrument_id": "BTCUSDTPERP",
                 //             "index_price": "20141.9967",
                 //             "mark_price": "20139.3404",
                 //             "max_buy_price": "21146.4838",
                 //             "min_sell_price": "19132.2725",
                 //             "best_bid": "20140.0998",
                 //             "best_bid_size": "3116",
                 //             "best_ask": "20140.0999",
                 //             "best_ask_size": "9004",
                 //             "high_24h": "20410.6496",
                 //             "open_24h": "20308.6998",
                 //             "low_24h": "19600",
                 //             "last": "20140.0999",
                 //             "last_qty": "2",
                 //             "volume_24h": "49382816",
                 //             "price_change_percent": "-0.008301855936636448",
                 //             "open_interest": "-",
                 //             "timestamp": 1663221614998
                 //         }
                 //     }
                 //
                 std::any date =
                     this->safeInteger(response, std::string("date"));
                 std::any tickers = this->safeValue(
                     response, std::string("ticker"), ccxt::list{});
                 std::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::dict{});
                 std::any firstTicker =
                     this->safeValue(tickers, 0, ccxt::dict{});
                 std::any result = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   result = data;
                 } else {
                   result = this->extend(
                       ccxt::dict{
                           {std::string("date"), date},
                       },
                       firstTicker);
                 }
                 if (isTrue(isEqual(result, std::any{}))) {
                   throw NullResponse(toString(add(
                       this->id,
                       std::string(" fetchTicker() returned empty response"))));
                 }
                 return this->parseTicker(result, market);
               })
        .share();
  }

  std::any parseTicker(std::any ticker, std::any market = std::any{}) override {
    //
    // spot: fetchTicker, fetchTickers
    //
    //     {
    //         "last":0.021957,
    //         "symbol": "btc_usdt",
    //         "base_vol":2249.3521732227,
    //         "change":-0.6,
    //         "vol":102443.5111,
    //         "sell":0.021978,
    //         "low":0.021791,
    //         "buy":0.021946,
    //         "high":0.022266,
    //         "date"1564518452, // injected from fetchTicker/fetchTickers
    //     }
    //
    // swap: fetchTicker, fetchTickers
    //
    //     {
    //         "instrument_id": "BTCUSDTPERP",
    //         "index_price": "20141.9967",
    //         "mark_price": "20139.3404",
    //         "max_buy_price": "21146.4838",
    //         "min_sell_price": "19132.2725",
    //         "best_bid": "20140.0998",
    //         "best_bid_size": "3116",
    //         "best_ask": "20140.0999",
    //         "best_ask_size": "9004",
    //         "high_24h": "20410.6496",
    //         "open_24h": "20308.6998",
    //         "low_24h": "19600",
    //         "last": "20140.0999",
    //         "last_qty": "2",
    //         "volume_24h": "49382816",
    //         "price_change_percent": "-0.008301855936636448",
    //         "open_interest": "-",
    //         "timestamp": 1663221614998
    //     }
    //
    std::any indexPrice = this->safeNumber(ticker, std::string("index_price"));
    std::any marketType = (isTrue((!isEqual(indexPrice, std::any{})))
                               ? std::any(std::string("contract"))
                               : std::any(std::string("spot")));
    std::any marketId = this->safeStringUpper2(ticker, std::string("symbol"),
                                               std::string("instrument_id"));
    std::any symbol =
        this->safeSymbol(marketId, market, std::any{}, marketType);
    market = this->safeMarket(marketId, market, std::any{}, marketType);
    std::any timestamp = this->safeTimestamp(ticker, std::string("date"));
    if (isTrue(isEqual(::getValue(market, std::string("swap")), true))) {
      timestamp = this->safeInteger(ticker, std::string("timestamp"));
    }
    std::any last = this->safeString(ticker, std::string("last"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"), this->safeString2(ticker, std::string("high"),
                                                    std::string("high_24h"))},
            {std::string("low"), this->safeString2(ticker, std::string("low"),
                                                   std::string("low_24h"))},
            {std::string("bid"), this->safeString2(ticker, std::string("buy"),
                                                   std::string("best_bid"))},
            {std::string("bidVolume"),
             this->safeString(ticker, std::string("best_bid_size"))},
            {std::string("ask"), this->safeString2(ticker, std::string("sell"),
                                                   std::string("best_ask"))},
            {std::string("askVolume"),
             this->safeString(ticker, std::string("best_ask_size"))},
            {std::string("vwap"), std::any{}},
            {std::string("open"),
             this->safeString(ticker, std::string("open_24h"))},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"), std::any{}},
            {std::string("change"), std::any{}},
            {std::string("percentage"),
             this->safeString2(ticker, std::string("change"),
                               std::string("price_change_percent"))},
            {std::string("average"), std::any{}},
            {std::string("baseVolume"),
             this->safeString2(ticker, std::string("vol"),
                               std::string("volume_24h"))},
            {std::string("quoteVolume"),
             this->safeString(ticker, std::string("base_vol"))},
            {std::string("markPrice"),
             this->safeString(ticker, std::string("mark_price"))},
            {std::string("indexPrice"), indexPrice},
            {std::string("info"), ticker},
        },
        market);
  }

  std::any parseTrade(std::any trade, std::any market = std::any{}) override {
    //
    // spot: fetchTrades
    //
    //     {
    //         "date":1564520003,
    //         "id":1596149203,
    //         "amount":0.7073,
    //         "type":"buy",
    //         "price":0.02193,
    //     }
    //
    // swap: fetchTrades
    //
    //     {
    //         "instrument_id": "BTCUSDTPERP",
    //         "trade_id": "1595190773677035521",
    //         "direction": "4",
    //         "volume": "4",
    //         "price": "16188.3",
    //         "trade_time": 1669158092314
    //     }
    //
    // spot: fetchMyTrades
    //
    //     {
    //         "symbol": "BTC_USDT",
    //         "order_id": "6707cbdcda0edfaa7f4ab509e4cbf966",
    //         "id": 28457,
    //         "price": 0.1,
    //         "amount": 0,
    //         "fee": 0.096,
    //         "fee_currency": "USDT",
    //         "timestamp": 1499865549,
    //         "side": "buy", // or "side": "sell_market"
    //         "is_maker": true
    //     }
    //
    // swap: fetchMyTrades
    //
    //     {
    //         "trade_id": "1590136768424841218",
    //         "instrument_id": "BTCUSDTPERP",
    //         "order_id": "1590136768156405760",
    //         "type": 1,
    //         "order_type": 8,
    //         "price": "18514.5",
    //         "size": "1",
    //         "fee": "0.00925725",
    //         "close_profit": "0",
    //         "leverage": "20",
    //         "trade_type": 0,
    //         "match_role": 1,
    //         "trade_time": 1667953123562
    //     }
    //
    std::any id =
        this->safeString2(trade, std::string("id"), std::string("trade_id"));
    std::any orderId = this->safeString(trade, std::string("order_id"));
    std::any priceString = this->safeString(trade, std::string("price"));
    std::any amountString = this->safeStringN(
        trade, ccxt::list{std::string("amount"), std::string("volume"),
                          std::string("size")});
    std::any marketId = this->safeStringUpper2(trade, std::string("symbol"),
                                               std::string("instrument_id"));
    std::any symbol = this->safeSymbol(marketId, market);
    if (isTrue(isEqual(market, std::any{}))) {
      market = this->safeMarket(marketId);
    }
    std::any timestamp = this->safeTimestamp2(trade, std::string("date"),
                                              std::string("timestamp"));
    std::any side =
        this->safeString2(trade, std::string("type"), std::string("side"));
    std::any type = std::any{};
    std::any takerOrMaker = std::any{};
    if (isTrue(isEqual(::getValue(market, std::string("type")),
                       std::string("swap")))) {
      timestamp = this->safeInteger(trade, std::string("trade_time"));
      std::any orderType = this->safeString(trade, std::string("order_type"));
      std::any tradeRole = this->safeString(trade, std::string("match_role"));
      std::any direction = this->safeString(trade, std::string("direction"));
      if (isTrue(!isEqual(orderType, std::any{}))) {
        type = (isTrue((isEqual(orderType, std::string("0"))))
                    ? std::any(std::string("limit"))
                    : std::any(std::any{}));
      }
      if (isTrue(isEqual(tradeRole, std::string("1")))) {
        takerOrMaker = std::string("taker");
      } else if (isTrue(isEqual(tradeRole, std::string("2")))) {
        takerOrMaker = std::string("maker");
      } else {
        takerOrMaker = std::any{};
      }
      if (isTrue(isTrue((isEqual(side, std::string("1")))) ||
                 isTrue((isEqual(direction, std::string("1")))))) {
        // side = 'open long';
        side = std::string("buy");
      } else if (isTrue(isTrue((isEqual(side, std::string("2")))) ||
                        isTrue((isEqual(direction, std::string("2")))))) {
        // side = 'open short';
        side = std::string("sell");
      } else if (isTrue(isTrue((isEqual(side, std::string("3")))) ||
                        isTrue((isEqual(direction, std::string("3")))))) {
        // side = 'close long';
        side = std::string("sell");
      } else if (isTrue(isTrue((isEqual(side, std::string("4")))) ||
                        isTrue((isEqual(direction, std::string("4")))))) {
        // side = 'close short';
        side = std::string("buy");
      }
    } else {
      if (isTrue(isEqual(side, std::any{}))) {
        throw ExchangeError(toString(
            add(this->id, std::string(" parseTrade() returned no side"))));
      }
      std::any parts = split(side, std::string("_"));
      side = this->safeString(parts, 0);
      type = this->safeString(parts, 1);
      if (isTrue(isEqual(type, std::any{}))) {
        type = std::string("limit");
      }
      std::any isMaker = this->safeValue(trade, std::string("is_maker"));
      takerOrMaker =
          (isTrue((isEqual(isMaker, true))) ? std::any(std::string("maker"))
                                            : std::any(std::string("taker")));
    }
    std::any fee = std::any{};
    std::any feeCostString = this->safeString(trade, std::string("fee"));
    if (isTrue(!isEqual(feeCostString, std::any{}))) {
      std::any feeCurrencyId =
          this->safeString(trade, std::string("fee_currency"));
      std::any feeCurrencyCode = std::any{};
      if (isTrue(!isEqual(feeCurrencyId, std::any{}))) {
        feeCurrencyCode = this->safeCurrencyCode(feeCurrencyId);
      }
      fee = ccxt::dict{
          {std::string("cost"), feeCostString},
          {std::string("currency"), feeCurrencyCode},
      };
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("info"), trade},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("type"), type},
            {std::string("order"), orderId},
            {std::string("side"), side},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), std::any{}},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("fee"), fee},
        },
        market);
  }

  /**
   * @method
   * @name digifinex#fetchTime
   * @description fetches the current integer timestamp in milliseconds from the
   * exchange server
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#server-timestamp
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int} the current integer timestamp in milliseconds from the
   * exchange server
   */
  std::shared_future<std::any>
  fetchTime(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any response =
                            awaitValue(this->publicSpotGetTime(params));
                        //
                        //     {
                        //         "server_time": 1589873762,
                        //         "code": 0
                        //     }
                        //
                        return this->safeTimestamp(response,
                                                   std::string("server_time"));
                      })
        .share();
  }

  /**
   * @method
   * @name digifinex#fetchStatus
   * @description the latest known information on the availability of the
   * exchange API
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#server-ping
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [status structure]{@link
   * https://docs.ccxt.com/?id=exchange-status-structure}
   */
  std::shared_future<std::any>
  fetchStatus(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any response =
                            awaitValue(this->publicSpotGetPing(params));
                        //
                        //     {
                        //         "msg": "pong",
                        //         "code": 0
                        //     }
                        //
                        std::any code =
                            this->safeInteger(response, std::string("code"));
                        std::any status =
                            (isTrue((isEqual(code, 0)))
                                 ? std::any(std::string("ok"))
                                 : std::any(std::string("maintenance")));
                        return ccxt::dict{
                            {std::string("status"), status},
                            {std::string("updated"), std::any{}},
                            {std::string("eta"), std::any{}},
                            {std::string("url"), std::any{}},
                            {std::string("info"), response},
                        };
                      })
        .share();
  }

  /**
   * @method
   * @name digifinex#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#get-recent-trades
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#recenttrades
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<std::any>
  fetchTrades(std::any symbol, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(
                       request, std::string("limit"),
                       (isTrue((isEqual(::getValue(market, std::string("swap")),
                                        true)))
                            ? std::any(mathMin(limit, 100))
                            : std::any(limit)));
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   ::setValue(request, std::string("instrument_id"),
                              ::getValue(market, std::string("id")));
                   response = awaitValue(this->publicSwapGetPublicTrades(
                       this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   response = awaitValue(this->publicSpotGetTrades(
                       this->extend(request, params)));
                 }
                 //
                 // spot
                 //
                 //     {
                 //         "data":[
                 //             {
                 //                 "date":1564520003,
                 //                 "id":1596149203,
                 //                 "amount":0.7073,
                 //                 "type":"buy",
                 //                 "price":0.02193,
                 //             },
                 //             {
                 //                 "date":1564520002,
                 //                 "id":1596149165,
                 //                 "amount":0.3232,
                 //                 "type":"sell",
                 //                 "price":0.021927,
                 //             },
                 //         ],
                 //         "code": 0,
                 //         "date": 1564520003,
                 //     }
                 //
                 // swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": [
                 //             {
                 //                 "instrument_id": "BTCUSDTPERP",
                 //                 "trade_id": "1595190773677035521",
                 //                 "direction": "4",
                 //                 "volume": "4",
                 //                 "price": "16188.3",
                 //                 "trade_time": 1669158092314
                 //             },
                 //             ...
                 //         ]
                 //     }
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseTrades(data, market, since, limit);
               })
        .share();
  }

  std::any parseOHLCV(std::any ohlcv, std::any market = std::any{}) override {
    //
    //     [
    //         1556712900,
    //         2205.899,
    //         0.029967,
    //         0.02997,
    //         0.029871,
    //         0.029927
    //     ]
    //
    if (isTrue(isEqual(this->safeBool(market, std::string("swap")), true))) {
      return ccxt::list{
          this->safeInteger(ohlcv, 0), this->safeNumber(ohlcv, 1),
          this->safeNumber(ohlcv, 2),  this->safeNumber(ohlcv, 3),
          this->safeNumber(ohlcv, 4),  this->safeNumber(ohlcv, 5)};
    } else {
      return ccxt::list{
          this->safeTimestamp(ohlcv, 0), this->safeNumber(ohlcv, 5),
          this->safeNumber(ohlcv, 3),    this->safeNumber(ohlcv, 4),
          this->safeNumber(ohlcv, 2),    this->safeNumber(ohlcv, 1)};
    }
  }

  /**
   * @method
   * @name digifinex#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#get-candles-data
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#recentcandle
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest candle to fetch
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
             std::any since = std::any{}, std::any limit = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any market = this->market(symbol);
                std::any request = ccxt::dict{};
                std::any response = std::any{};
                if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                   true))) {
                  ::setValue(request, std::string("instrument_id"),
                             ::getValue(market, std::string("id")));
                  ::setValue(request, std::string("granularity"), timeframe);
                  if (isTrue(!isEqual(limit, std::any{}))) {
                    ::setValue(request, std::string("limit"),
                               mathMin(limit, 100));
                  }
                  response = awaitValue(this->publicSwapGetPublicCandles(
                      this->extend(request, params)));
                } else {
                  std::any until =
                      this->safeInteger(params, std::string("until"));
                  ::setValue(request, std::string("symbol"),
                             ::getValue(market, std::string("id")));
                  ::setValue(
                      request, std::string("period"),
                      this->safeString(this->timeframes, timeframe, timeframe));
                  std::any startTime = since;
                  std::any duration = this->parseTimeframe(timeframe);
                  if (isTrue(isEqual(startTime, std::any{}))) {
                    if (isTrue(isTrue((!isEqual(limit, std::any{}))) ||
                               isTrue((!isEqual(until, std::any{}))))) {
                      std::any endTime = (isTrue((!isEqual(until, std::any{})))
                                              ? std::any(until)
                                              : std::any(this->milliseconds()));
                      std::any startLimit =
                          (isTrue((!isEqual(limit, std::any{})))
                               ? std::any(limit)
                               : std::any(200));
                      startTime = subtract(
                          endTime,
                          (multiply(multiply(startLimit, duration), 1000)));
                    }
                  }
                  if (isTrue(!isEqual(startTime, std::any{}))) {
                    startTime = this->parseToInt(divide(startTime, 1000));
                    ::setValue(request, std::string("start_time"), startTime);
                    if (isTrue(isTrue((!isEqual(limit, std::any{}))) ||
                               isTrue((!isEqual(until, std::any{}))))) {
                      if (isTrue(!isEqual(until, std::any{}))) {
                        std::any endByUntil =
                            this->parseToInt(divide(until, 1000));
                        if (isTrue(!isEqual(limit, std::any{}))) {
                          std::any endByLimit =
                              this->sum(startTime, multiply(limit, duration));
                          ::setValue(request, std::string("end_time"),
                                     mathMin(endByLimit, endByUntil));
                        } else {
                          ::setValue(request, std::string("end_time"),
                                     endByUntil);
                        }
                      } else {
                        if (isTrue(isEqual(limit, std::any{}))) {
                          throw ArgumentsRequired(toString(add(
                              this->id,
                              std::string(
                                  " fetchOHLCV() requires a limit argument"))));
                        }
                        ::setValue(
                            request, std::string("end_time"),
                            this->sum(startTime, multiply(limit, duration)));
                      }
                    }
                  }
                  params = this->omit(params, std::string("until"));
                  response = awaitValue(
                      this->publicSpotGetKline(this->extend(request, params)));
                }
                //
                // spot
                //
                //     {
                //         "code":0,
                //         "data":[
                //             [1556712900,2205.899,0.029967,0.02997,0.029871,0.029927],
                //             [1556713800,1912.9174,0.029992,0.030014,0.029955,0.02996],
                //             [1556714700,1556.4795,0.029974,0.030019,0.029969,0.02999],
                //         ]
                //     }
                //
                // swap
                //
                //     {
                //         "code": 0,
                //         "data": {
                //             "instrument_id": "BTCUSDTPERP",
                //             "granularity": "1m",
                //             "candles": [
                //                 [1588089660000,"6900","6900","6900","6900","0","0"],
                //                 [1588089720000,"6900","6900","6900","6900","0","0"],
                //                 [1588089780000,"6900","6900","6900","6900","0","0"],
                //             ]
                //         }
                //     }
                //
                std::any candles = std::any{};
                if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                   true))) {
                  std::any data = this->safeValue(response, std::string("data"),
                                                  ccxt::dict{});
                  candles = this->safeValue(data, std::string("candles"),
                                            ccxt::list{});
                } else {
                  candles = this->safeValue(response, std::string("data"),
                                            ccxt::list{});
                }
                return this->parseOHLCVs(candles, market, timeframe, since,
                                         limit);
              })
            .share();
  }

  /**
   * @method
   * @name digifinex#createOrder
   * @description create a trade order
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#create-new-order
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#orderplace
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much you want to trade in units of the base
   * currency, spot market orders use the quote currency, swap requires the
   * number of contracts
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.timeInForce] "GTC", "IOC", "FOK", or "PO"
   * @param {bool} [params.postOnly] true or false
   * @param {bool} [params.reduceOnly] true or false
   * @param {string} [params.marginMode] 'cross' or 'isolated', for spot margin
   * trading
   * @param {float} [params.cost] *spot market buy only* the quote quantity that
   * can be used as an alternative for the amount
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any marginResult = this->handleMarginModeAndParams(
                     std::string("createOrder"), params);
                 std::any marginMode = ::getValue(marginResult, 0);
                 std::any request = this->createOrderRequest(
                     symbol, type, side, amount, price, params);
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   response = awaitValue(
                       this->privateSwapPostTradeOrderPlace(request));
                 } else {
                   if (isTrue(!isEqual(marginMode, std::any{}))) {
                     response = awaitValue(
                         this->privateSpotPostMarginOrderNew(request));
                   } else {
                     response =
                         awaitValue(this->privateSpotPostSpotOrderNew(request));
                   }
                 }
                 //
                 // spot and margin
                 //
                 //     {
                 //         "code": 0,
                 //         "order_id": "198361cecdc65f9c8c9bb2fa68faec40"
                 //     }
                 //
                 // swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": "1590873693003714560"
                 //     }
                 //
                 if (isTrue(isEqual(response, std::any{}))) {
                   throw NullResponse(toString(add(
                       this->id,
                       std::string(" createOrder() returned empty response"))));
                 }
                 std::any order = this->parseOrder(response, market);
                 ::setValue(order, std::string("symbol"),
                            ::getValue(market, std::string("symbol")));
                 ::setValue(order, std::string("type"), type);
                 ::setValue(order, std::string("side"), side);
                 ::setValue(order, std::string("amount"), amount);
                 ::setValue(order, std::string("price"), price);
                 return order;
               })
        .share();
  }

  /**
   * @method
   * @name digifinex#createOrders
   * @description create a list of trade orders (all orders should be of the
   * same symbol)
   * @see
   * https://docs.digifinex.com/en-ww/spot/v3/rest.html#create-multiple-order
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#batchorder
   * @param {Array} orders list of orders to create, each object should contain
   * the parameters required by createOrder, namely symbol, type, side, amount,
   * price and params
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrders(std::any orders, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any ordersRequests = ccxt::list{};
                 std::any symbol = std::any{};
                 std::any marginMode = std::any{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   std::any rawOrder = ::getValue(orders, i);
                   std::any marketId =
                       this->safeString(rawOrder, std::string("symbol"));
                   if (isTrue(isEqual(symbol, std::any{}))) {
                     symbol = marketId;
                   } else {
                     if (isTrue(!isEqual(symbol, marketId))) {
                       throw BadRequest(toString(
                           add(this->id,
                               std::string(" createOrders() requires all "
                                           "orders to have the same symbol"))));
                     }
                   }
                   std::any type =
                       this->safeString(rawOrder, std::string("type"));
                   std::any side =
                       this->safeString(rawOrder, std::string("side"));
                   std::any amount =
                       this->safeValue(rawOrder, std::string("amount"));
                   std::any price =
                       this->safeValue(rawOrder, std::string("price"));
                   std::any orderParams = this->safeValue(
                       rawOrder, std::string("params"), ccxt::dict{});
                   std::any marginResult = this->handleMarginModeAndParams(
                       std::string("createOrders"), orderParams);
                   std::any currentMarginMode = ::getValue(marginResult, 0);
                   if (isTrue(!isEqual(currentMarginMode, std::any{}))) {
                     if (isTrue(isEqual(marginMode, std::any{}))) {
                       marginMode = currentMarginMode;
                     } else {
                       if (isTrue(!isEqual(marginMode, currentMarginMode))) {
                         throw BadRequest(toString(add(
                             this->id,
                             std::string(
                                 " createOrders() requires all orders to have "
                                 "the same margin mode (isolated or cross)"))));
                       }
                     }
                   }
                   std::any orderRequest = this->createOrderRequest(
                       marketId, type, side, amount, price, orderParams);
                   arrayPush(ordersRequests, orderRequest);
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{};
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   response = awaitValue(
                       this->privateSwapPostTradeBatchOrder(ordersRequests));
                 } else {
                   ::setValue(request, std::string("market"),
                              (isTrue((!isEqual(marginMode, std::any{})))
                                   ? std::any(std::string("margin"))
                                   : std::any(std::string("spot"))));
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   ::setValue(request, std::string("list"),
                              this->json(ordersRequests));
                   response = awaitValue(
                       this->privateSpotPostMarketOrderBatchNew(request));
                 }
                 //
                 // spot
                 //
                 //     {
                 //         "code": 0,
                 //         "order_ids": [
                 //             "064290fbe2d26e7b28d7e6c0a5cf70a5",
                 //             "24c8f9b73d81e4d9d8d7e3280281c258"
                 //         ]
                 //     }
                 //
                 // swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": [
                 //             "1720297963537829888",
                 //             "1720297963537829889"
                 //         ]
                 //     }
                 //
                 std::any data = ccxt::list{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   data = this->safeValue(response, std::string("data"),
                                          ccxt::list{});
                 } else {
                   data = this->safeValue(response, std::string("order_ids"),
                                          ccxt::list{});
                 }
                 std::any result = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   std::any rawOrder = ::getValue(orders, i);
                   std::any individualOrder = ccxt::dict{};
                   ::setValue(individualOrder, std::string("order_id"),
                              ::getValue(data, i));
                   ::setValue(individualOrder, std::string("instrument_id"),
                              ::getValue(market, std::string("id")));
                   ::setValue(
                       individualOrder, std::string("amount"),
                       this->safeNumber(rawOrder, std::string("amount")));
                   ::setValue(individualOrder, std::string("price"),
                              this->safeNumber(rawOrder, std::string("price")));
                   arrayPush(result, individualOrder);
                 }
                 return this->parseOrders(result, market);
               })
        .share();
  }

  virtual std::any createOrderRequest(std::any symbol, std::any type,
                                      std::any side, std::any amount,
                                      std::any price = std::any{},
                                      std::any params = ccxt::dict{}) {
    if (isTrue(isEqual(type, std::any{}))) {
      throw ArgumentsRequired(
          toString(add(this->id, std::string(" requires a type argument"))));
    }
    if (isTrue(isEqual(side, std::any{}))) {
      throw ArgumentsRequired(
          toString(add(this->id, std::string(" requires a side argument"))));
    }
    /**
     * @method
     * @ignore
     * @name digifinex#createOrderRequest
     * @description helper function to build request
     * @param {string} symbol unified symbol of the market to create an order in
     * @param {string} type 'market' or 'limit'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much you want to trade in units of the base
     * currency, spot market orders use the quote currency, swap requires the
     * number of contracts
     * @param {float} [price] the price at which the order is to be fulfilled,
     * in units of the quote currency, ignored in market orders
     * @param {object} [params] extra parameters specific to the exchange API
     * endpoint
     * @returns {object} request to be sent to the exchange
     */
    std::any market = this->market(symbol);
    std::any marketType = std::any{};
    std::any marginMode = std::any{};
    std::any marketTypeparamsVariable = this->handleMarketTypeAndParams(
        std::string("createOrderRequest"), market, params);
    marketType = ::getValue(marketTypeparamsVariable, 0);
    params = ::getValue(marketTypeparamsVariable, 1);
    std::any marginModeparamsVariable = this->handleMarginModeAndParams(
        std::string("createOrderRequest"), params);
    marginMode = ::getValue(marginModeparamsVariable, 0);
    params = ::getValue(marginModeparamsVariable, 1);
    if (isTrue(!isEqual(marginMode, std::any{}))) {
      marketType = std::string("margin");
    }
    std::any request = ccxt::dict{};
    std::any swap = (isEqual(marketType, std::string("swap")));
    std::any isMarketOrder = (isEqual(type, std::string("market")));
    std::any isLimitOrder = (isEqual(type, std::string("limit")));
    std::any marketIdRequest =
        (isTrue(swap) ? std::any(std::string("instrument_id"))
                      : std::any(std::string("symbol")));
    ::setValue(request, marketIdRequest, ::getValue(market, std::string("id")));
    std::any postOnly = this->isPostOnly(isMarketOrder, false, params);
    std::any postOnlyParsed = std::any{};
    if (isTrue(swap)) {
      std::any reduceOnly =
          this->safeBool(params, std::string("reduceOnly"), false);
      std::any timeInForce =
          this->safeString(params, std::string("timeInForce"));
      std::any orderType = std::any{};
      if (isTrue(isEqual(side, std::string("buy")))) {
        std::any requestType =
            (isTrue((isEqual(reduceOnly, true))) ? std::any(4) : std::any(1));
        ::setValue(request, std::string("type"), requestType);
      } else {
        std::any requestType =
            (isTrue((isEqual(reduceOnly, true))) ? std::any(3) : std::any(2));
        ::setValue(request, std::string("type"), requestType);
      }
      if (isTrue(isLimitOrder)) {
        orderType = 0;
      }
      if (isTrue(isEqual(timeInForce, std::string("FOK")))) {
        orderType = (isTrue(isMarketOrder) ? std::any(15) : std::any(9));
      } else if (isTrue(isEqual(timeInForce, std::string("IOC")))) {
        orderType = (isTrue(isMarketOrder) ? std::any(13) : std::any(4));
      } else if (isTrue(isTrue((isEqual(timeInForce, std::string("GTC")))) ||
                        isTrue((isMarketOrder)))) {
        orderType = 14;
      } else if (isTrue(isEqual(timeInForce, std::string("PO")))) {
        postOnly = true;
      }
      if (isTrue(!isEqual(price, std::any{}))) {
        ::setValue(request, std::string("price"),
                   this->priceToPrecision(symbol, price));
      }
      ::setValue(request, std::string("order_type"), orderType);
      ::setValue(request, std::string("size"),
                 amount); // swap orders require the amount to be the number of
                          // contracts
      params = this->omit(params, ccxt::list{std::string("reduceOnly"),
                                             std::string("timeInForce")});
    } else {
      postOnlyParsed =
          (isTrue((isEqual(postOnly, true))) ? std::any(1) : std::any(2));
      ::setValue(request, std::string("market"), marketType);
      std::any suffix = std::string("");
      if (isTrue(isEqual(type, std::string("market")))) {
        suffix = std::string("_market");
      } else {
        ::setValue(request, std::string("price"),
                   this->priceToPrecision(symbol, price));
      }
      ::setValue(request, std::string("type"), add(side, suffix));
      // limit orders require the amount in the base currency, market orders
      // require the amount in the quote currency
      std::any quantity = std::any{};
      std::any createMarketBuyOrderRequiresPrice = true;
      std::any createMarketBuyOrderRequiresPriceparamsVariable =
          this->handleOptionAndParams(
              params, std::string("createOrderRequest"),
              std::string("createMarketBuyOrderRequiresPrice"), true);
      createMarketBuyOrderRequiresPrice =
          ::getValue(createMarketBuyOrderRequiresPriceparamsVariable, 0);
      params = ::getValue(createMarketBuyOrderRequiresPriceparamsVariable, 1);
      if (isTrue(isTrue(isMarketOrder) &&
                 isTrue((isEqual(side, std::string("buy")))))) {
        std::any cost = this->safeNumber(params, std::string("cost"));
        params = this->omit(params, std::string("cost"));
        if (isTrue(!isEqual(cost, std::any{}))) {
          quantity = this->costToPrecision(symbol, cost);
        } else if (isTrue(createMarketBuyOrderRequiresPrice)) {
          if (isTrue(isEqual(price, std::any{}))) {
            throw InvalidOrder(toString(
                add(this->id,
                    std::string(
                        " createOrder() requires a price argument for market "
                        "buy orders on spot markets to calculate the total "
                        "amount to spend (amount * price), alternatively set "
                        "the createMarketBuyOrderRequiresPrice option or param "
                        "to false and pass the cost to spend in the amount "
                        "argument"))));
          } else {
            std::any amountString = this->numberToString(amount);
            std::any priceString = this->numberToString(price);
            std::any costRequest = this->parseNumber(
                ccxt::Precise::stringMul(amountString, priceString));
            quantity = this->costToPrecision(symbol, costRequest);
          }
        } else {
          quantity = this->costToPrecision(symbol, amount);
        }
      } else {
        quantity = this->amountToPrecision(symbol, amount);
      }
      ::setValue(request, std::string("amount"), quantity);
    }
    if (isTrue(postOnly)) {
      if (isTrue(isTrue((!isEqual(postOnlyParsed, std::any{}))) &&
                 isTrue((!isEqual(postOnlyParsed, 0))))) {
        ::setValue(request, std::string("post_only"), postOnlyParsed);
      } else {
        ::setValue(request, std::string("post_only"), postOnly);
      }
    }
    params = this->omit(params, ccxt::list{std::string("postOnly")});
    return this->extend(request, params);
  }

  /**
   * @method
   * @name digifinex#createMarketBuyOrderWithCost
   * @description create a market buy order by providing the symbol and cost
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#create-new-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {float} cost how much you want to trade in units of the quote
   * currency
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createMarketBuyOrderWithCost(std::any symbol, std::any cost,
                               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("spot")),
                                     true))) {
                   throw NotSupported(toString(add(
                       this->id, std::string(" createMarketBuyOrderWithCost() "
                                             "supports spot orders only"))));
                 }
                 ::setValue(params,
                            std::string("createMarketBuyOrderRequiresPrice"),
                            false);
                 return awaitValue(this->createOrder(
                     symbol, std::string("market"), std::string("buy"), cost,
                     std::any{}, params));
               })
        .share();
  }

  /**
   * @method
   * @name digifinex#cancelOrder
   * @description cancels an open order
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#cancel-order
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#cancelorder
   * @param {string} id order id
   * @param {string} symbol not used by cancelOrder ()
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelOrder(std::any id, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 id = toString(id);
                 std::any marketType = std::any{};
                 std::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(std::string("cancelOrder"),
                                                     market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 std::any request = ccxt::dict{
                     {std::string("order_id"), id},
                 };
                 if (isTrue(isEqual(marketType, std::string("swap")))) {
                   if (isTrue(isEqual(symbol, std::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id,
                         std::string(
                             " cancelOrder() requires a symbol argument"))));
                   }
                   ::setValue(request, std::string("instrument_id"),
                              this->safeString(market, std::string("id")));
                 } else {
                   ::setValue(request, std::string("market"), marketType);
                 }
                 std::any marginModequeryVariable =
                     this->handleMarginModeAndParams(std::string("cancelOrder"),
                                                     params);
                 std::any marginMode = ::getValue(marginModequeryVariable, 0);
                 std::any query = ::getValue(marginModequeryVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(
                         isTrue(!isEqual(marginMode, std::any{})) ||
                         isTrue(isEqual(marketType, std::string("margin"))))) {
                   marketType = std::string("margin");
                   response = awaitValue(this->privateSpotPostMarginOrderCancel(
                       this->extend(request, query)));
                 } else if (isTrue(isEqual(marketType, std::string("spot")))) {
                   response = awaitValue(this->privateSpotPostSpotOrderCancel(
                       this->extend(request, query)));
                 } else if (isTrue(isEqual(marketType, std::string("swap")))) {
                   response = awaitValue(this->privateSwapPostTradeCancelOrder(
                       this->extend(request, query)));
                 } else {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(
                           " cancelOrder() not support this market type"))));
                 }
                 //
                 // spot and margin
                 //
                 //     {
                 //         "code": 0,
                 //         "success": [
                 //             "198361cecdc65f9c8c9bb2fa68faec40",
                 //             "3fb0d98e51c18954f10d439a9cf57de0"
                 //         ],
                 //         "error": [
                 //             "78a7104e3c65cc0c5a212a53e76d0205"
                 //         ]
                 //     }
                 //
                 // swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": "1590923061186531328"
                 //     }
                 //
                 if (isTrue(
                         isTrue((isEqual(marketType, std::string("spot")))) ||
                         isTrue(
                             (isEqual(marketType, std::string("margin")))))) {
                   std::any canceledOrders = this->safeValue(
                       response, std::string("success"), ccxt::list{});
                   std::any numCanceledOrders = getArrayLength(canceledOrders);
                   if (isTrue(!isEqual(numCanceledOrders, 1))) {
                     throw OrderNotFound(toString(add(
                         add(add(this->id, std::string(" cancelOrder() ")), id),
                         std::string(" not found"))));
                   }
                   std::any orders = this->parseCancelOrders(response);
                   return this->safeDict(orders, 0);
                 } else {
                   return this->safeOrder(ccxt::dict{
                       {std::string("info"), response},
                       {std::string("orderId"),
                        this->safeString(response, std::string("data"))},
                   });
                 }
                 return std::any{};
               })
        .share();
  }

  virtual std::any parseCancelOrders(std::any response) {
    std::any success =
        this->safeList(response, std::string("success"), ccxt::list{});
    std::any error =
        this->safeList(response, std::string("error"), ccxt::list{});
    std::any result = ccxt::list{};
    for (std::any i = 0; isLessThan(i, getArrayLength(success));
         postFixIncrement(i)) {
      std::any order = ::getValue(success, i);
      arrayPush(result, this->safeOrder(ccxt::dict{
                            {std::string("info"), order},
                            {std::string("id"), order},
                            {std::string("status"), std::string("canceled")},
                        }));
    }
    for (std::any i = 0; isLessThan(i, getArrayLength(error));
         postFixIncrement(i)) {
      std::any order = ::getValue(error, i);
      arrayPush(result,
                this->safeOrder(ccxt::dict{
                    {std::string("info"), order},
                    {std::string("id"),
                     this->safeString2(order, std::string("order-id"),
                                       std::string("order_id"))},
                    {std::string("status"), std::string("failed")},
                    {std::string("clientOrderId"),
                     this->safeString(order, std::string("client-order-id"))},
                }));
    }
    return result;
  }

  /**
   * @method
   * @name digifinex#cancelOrders
   * @description cancel multiple orders
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#cancel-order
   * @param {string[]} ids order ids
   * @param {string} symbol not used by cancelOrders ()
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelOrders(std::any ids, std::any symbol = std::any{},
               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any defaultType =
                     this->safeString(this->options, std::string("defaultType"),
                                      std::string("spot"));
                 std::any orderType =
                     this->safeString(params, std::string("type"), defaultType);
                 params = this->omit(params, std::string("type"));
                 std::any request = ccxt::dict{
                     {std::string("market"), orderType},
                     {std::string("order_id"), join(ids, std::string(","))},
                 };
                 std::any response =
                     awaitValue(this->privateSpotPostSpotOrderCancel(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": 0,
                 //         "success": [
                 //             "198361cecdc65f9c8c9bb2fa68faec40",
                 //             "3fb0d98e51c18954f10d439a9cf57de0"
                 //         ],
                 //         "error": [
                 //             "78a7104e3c65cc0c5a212a53e76d0205"
                 //         ]
                 //     }
                 //
                 return this->parseCancelOrders(response);
               })
        .share();
  }

  virtual std::any parseOrderStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("0"), std::string("open")},
        {std::string("1"), std::string("open")},
        {std::string("2"), std::string("closed")},
        {std::string("3"), std::string("canceled")},
        {std::string("4"), std::string("canceled")},
    };
    return this->safeString(statuses, status, status);
  }

  std::any parseOrder(std::any order, std::any market = std::any{}) override {
    //
    // spot: createOrder
    //
    //     {
    //         "code": 0,
    //         "order_id": "198361cecdc65f9c8c9bb2fa68faec40"
    //     }
    //
    // swap: createOrder
    //
    //     {
    //         "code": 0,
    //         "data": "1590873693003714560"
    //     }
    //
    // spot and swap: createOrders
    //
    //     {
    //         "order_id": "d64d92a5e0a120f792f385485bc3d95b",
    //         "instrument_id": "BTC_USDT",
    //         "amount": 0.0001,
    //         "price": 27000
    //     }
    //
    // spot: fetchOrder, fetchOpenOrders, fetchOrders
    //
    //     {
    //         "symbol": "BTC_USDT",
    //         "order_id": "dd3164b333a4afa9d5730bb87f6db8b3",
    //         "created_date": 1562303547,
    //         "finished_date": 0,
    //         "price": 0.1,
    //         "amount": 1,
    //         "cash_amount": 1,
    //         "executed_amount": 0,
    //         "avg_price": 0,
    //         "status": 1,
    //         "type": "buy",
    //         "kind": "margin"
    //     }
    //
    // swap: fetchOrder, fetchOpenOrders, fetchOrders
    //
    //     {
    //         "order_id": "1590898207657824256",
    //         "instrument_id": "BTCUSDTPERP",
    //         "margin_mode": "crossed",
    //         "contract_val": "0.001",
    //         "type": 1,
    //         "order_type": 0,
    //         "price": "14000",
    //         "size": "6",
    //         "filled_qty": "0",
    //         "price_avg": "0",
    //         "fee": "0",
    //         "state": 0,
    //         "leverage": "20",
    //         "turnover": "0",
    //         "has_stop": 0,
    //         "insert_time": 1668134664828,
    //         "time_stamp": 1668134664828
    //     }
    //
    std::any timestamp = std::any{};
    std::any lastTradeTimestamp = std::any{};
    std::any timeInForce = std::any{};
    std::any type = std::any{};
    std::any side = this->safeString(order, std::string("type"));
    std::any marketId = this->safeString2(order, std::string("symbol"),
                                          std::string("instrument_id"));
    std::any symbol = this->safeSymbol(marketId, market);
    market = this->market(symbol);
    if (isTrue(isEqual(::getValue(market, std::string("type")),
                       std::string("swap")))) {
      std::any orderType = this->safeInteger(order, std::string("order_type"));
      if (isTrue(!isEqual(orderType, std::any{}))) {
        if (isTrue(isTrue(isTrue(isTrue(isTrue((isEqual(orderType, 9))) ||
                                        isTrue((isEqual(orderType, 10)))) ||
                                 isTrue((isEqual(orderType, 11)))) ||
                          isTrue((isEqual(orderType, 12)))) ||
                   isTrue((isEqual(orderType, 15))))) {
          timeInForce = std::string("FOK");
        } else if (isTrue(
                       isTrue(isTrue(isTrue(isTrue((isEqual(orderType, 1))) ||
                                            isTrue((isEqual(orderType, 2)))) ||
                                     isTrue((isEqual(orderType, 3)))) ||
                              isTrue((isEqual(orderType, 4)))) ||
                       isTrue((isEqual(orderType, 13))))) {
          timeInForce = std::string("IOC");
        } else if (isTrue(isTrue(isTrue(isTrue((isEqual(orderType, 6))) ||
                                        isTrue((isEqual(orderType, 7)))) ||
                                 isTrue((isEqual(orderType, 8)))) ||
                          isTrue((isEqual(orderType, 14))))) {
          timeInForce = std::string("GTC");
        }
        if (isTrue(
                isTrue(isTrue(isTrue(isTrue(isTrue((isEqual(orderType, 0))) ||
                                            isTrue((isEqual(orderType, 1)))) ||
                                     isTrue((isEqual(orderType, 4)))) ||
                              isTrue((isEqual(orderType, 5)))) ||
                       isTrue((isEqual(orderType, 9)))) ||
                isTrue((isEqual(orderType, 10))))) {
          type = std::string("limit");
        } else {
          type = std::string("market");
        }
      }
      if (isTrue(isEqual(side, std::string("1")))) {
        side = std::string("open long");
      } else if (isTrue(isEqual(side, std::string("2")))) {
        side = std::string("open short");
      } else if (isTrue(isEqual(side, std::string("3")))) {
        side = std::string("close long");
      } else if (isTrue(isEqual(side, std::string("4")))) {
        side = std::string("close short");
      }
      timestamp = this->safeInteger(order, std::string("insert_time"));
      lastTradeTimestamp = this->safeInteger(order, std::string("time_stamp"));
    } else {
      timestamp = this->safeTimestamp(order, std::string("created_date"));
      lastTradeTimestamp =
          this->safeTimestamp(order, std::string("finished_date"));
      if (isTrue(!isEqual(side, std::any{}))) {
        std::any parts = split(side, std::string("_"));
        std::any numParts = getArrayLength(parts);
        if (isTrue(isGreaterThan(numParts, 1))) {
          side = ::getValue(parts, 0);
          type = ::getValue(parts, 1);
        } else {
          type = std::string("limit");
        }
      }
    }
    return this->safeOrder(
        ccxt::dict{
            {std::string("info"), order},
            {std::string("id"),
             this->safeString2(order, std::string("order_id"),
                               std::string("data"))},
            {std::string("clientOrderId"), std::any{}},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), lastTradeTimestamp},
            {std::string("symbol"), symbol},
            {std::string("type"), type},
            {std::string("timeInForce"), timeInForce},
            {std::string("postOnly"), std::any{}},
            {std::string("side"), side},
            {std::string("price"),
             this->safeNumber(order, std::string("price"))},
            {std::string("triggerPrice"), std::any{}},
            {std::string("amount"),
             this->safeNumber2(order, std::string("amount"),
                               std::string("size"))},
            {std::string("filled"),
             this->safeNumber2(order, std::string("executed_amount"),
                               std::string("filled_qty"))},
            {std::string("remaining"), std::any{}},
            {std::string("cost"), std::any{}},
            {std::string("average"),
             this->safeNumber2(order, std::string("avg_price"),
                               std::string("price_avg"))},
            {std::string("status"),
             this->parseOrderStatus(this->safeString2(
                 order, std::string("status"), std::string("state")))},
            {std::string("fee"),
             ccxt::dict{
                 {std::string("cost"),
                  this->safeNumber(order, std::string("fee"))},
             }},
            {std::string("trades"), std::any{}},
        },
        market);
  }

  /**
   * @method
   * @name digifinex#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see
   * https://docs.digifinex.com/en-ww/spot/v3/rest.html#current-active-orders
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#openorder
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of  open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOpenOrders(std::any symbol = std::any{}, std::any since = std::any{},
                  std::any limit = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any market = std::any{};
                if (isTrue(!isEqual(symbol, std::any{}))) {
                  market = this->market(symbol);
                }
                std::any marketType = std::any{};
                std::any marketTypeparamsVariable =
                    this->handleMarketTypeAndParams(
                        std::string("fetchOpenOrders"), market, params);
                marketType = ::getValue(marketTypeparamsVariable, 0);
                params = ::getValue(marketTypeparamsVariable, 1);
                std::any marginModequeryVariable =
                    this->handleMarginModeAndParams(
                        std::string("fetchOpenOrders"), params);
                std::any marginMode = ::getValue(marginModequeryVariable, 0);
                std::any query = ::getValue(marginModequeryVariable, 1);
                std::any request = ccxt::dict{};
                std::any swap = (isEqual(marketType, std::string("swap")));
                if (isTrue(swap)) {
                  if (isTrue(!isEqual(since, std::any{}))) {
                    ::setValue(request, std::string("start_timestamp"), since);
                  }
                  if (isTrue(!isEqual(limit, std::any{}))) {
                    ::setValue(request, std::string("limit"), limit);
                  }
                } else {
                  ::setValue(request, std::string("market"), marketType);
                }
                if (isTrue(!isEqual(market, std::any{}))) {
                  std::any marketIdRequest =
                      (isTrue(swap) ? std::any(std::string("instrument_id"))
                                    : std::any(std::string("symbol")));
                  ::setValue(request, marketIdRequest,
                             ::getValue(market, std::string("id")));
                }
                std::any response = std::any{};
                if (isTrue(
                        isTrue(!isEqual(marginMode, std::any{})) ||
                        isTrue(isEqual(marketType, std::string("margin"))))) {
                  marketType = std::string("margin");
                  response = awaitValue(this->privateSpotGetMarginOrderCurrent(
                      this->extend(request, query)));
                } else if (isTrue(isEqual(marketType, std::string("spot")))) {
                  response = awaitValue(this->privateSpotGetSpotOrderCurrent(
                      this->extend(request, query)));
                } else if (isTrue(isEqual(marketType, std::string("swap")))) {
                  response = awaitValue(this->privateSwapGetTradeOpenOrders(
                      this->extend(request, query)));
                } else {
                  throw NotSupported(toString(add(
                      this->id,
                      std::string(
                          " fetchOpenOrders() not support this market type"))));
                }
                //
                // spot and margin
                //
                //     {
                //         "code": 0,
                //         "data": [
                //             {
                //                 "symbol": "BTC_USDT",
                //                 "order_id":
                //                 "dd3164b333a4afa9d5730bb87f6db8b3",
                //                 "created_date": 1562303547,
                //                 "finished_date": 0,
                //                 "price": 0.1,
                //                 "amount": 1,
                //                 "cash_amount": 1,
                //                 "executed_amount": 0,
                //                 "avg_price": 0,
                //                 "status": 1,
                //                 "type": "buy",
                //                 "kind": "margin"
                //             }
                //         ]
                //     }
                //
                // swap
                //
                //     {
                //         "code": 0,
                //         "data": [
                //             {
                //                 "order_id": "1590898207657824256",
                //                 "instrument_id": "BTCUSDTPERP",
                //                 "margin_mode": "crossed",
                //                 "contract_val": "0.001",
                //                 "type": 1,
                //                 "order_type": 0,
                //                 "price": "14000",
                //                 "size": "6",
                //                 "filled_qty": "0",
                //                 "price_avg": "0",
                //                 "fee": "0",
                //                 "state": 0,
                //                 "leverage": "20",
                //                 "turnover": "0",
                //                 "has_stop": 0,
                //                 "insert_time": 1668134664828,
                //                 "time_stamp": 1668134664828
                //             },
                //             ...
                //         ]
                //     }
                //
                std::any data =
                    this->safeList(response, std::string("data"), ccxt::list{});
                return this->parseOrders(data, market, since, limit);
              })
            .share();
  }

